        sb.append("vin', icon: 'gos2vin', param: 'plate' }\n    ];\n\n    // ==========================================\n    // ВКЛАДКИ\n    // ==========================================\n    function switchTab(name) {\n        document.querySelectorAll('.tab-page').forEach(el => el.classList.remove('active'));\n        document.querySelectorAll('.nav-btn').forEach(el => el.classList.remove('active'));\n        document.getElementById('page-' + name).classList.add('active');\n        document.getElementById('nav' + name.charAt(0).toUpperCase() + name.slice(1)).classList.add('active');\n        if (name === 'history') renderHistory();\n        window.scrollTo(0, 0);\n    }\n\n    // ==========================================\n    // ИСТОРИЯ\n    // ==========================================\n    function loadHistory() {\n        try {\n            const raw = Storage.get(HISTORY_KEY);\n            if (!raw) return [];\n            const arr = JSON.parse(raw);\n            return Array.isArray(arr) ? arr : [];\n        } catch (e) { return []; }\n    }\n\n    function saveHistory(arr) {\n        try {\n            Storage.set(HISTORY_KEY, JSON.stringify(arr.slice(0, HISTORY_MAX)));\n        } catch (e) {}\n    }\n\n    function addToHistory(record) {\n        const arr = loadHistory();\n        arr.unshift(record);\n        saveHistory(arr);\n        updateHistoryBadge();\n    }\n\n    function removeFromHistory(id) {\n        const arr = loadHistory().filter(x => x.id !== id);\n        saveHistory(arr);\n        renderHistory();\n        updateHistoryBadge();\n    }\n\n    function clearHistory() {\n        if (!confirm('Удалить всю историю пробивов?')) return;\n        Storage.remove(HISTORY_KEY);\n        renderHistory();\n        updateHistoryBadge();\n    }\n\n    function updateHistoryBadge() {\n        const arr = loadHistory();\n        const badge = document.getElementById('navBadge');\n        if (arr.length > 0) {\n            badge.textContent = arr.length > 99 ? '99+' : arr.length;\n            badge.style.display = 'flex';\n        } else {\n            badge.style.display = 'none';\n        }\n        const clearBtn = document.getElementById('btnClearHistory');\n        if (arr.length > 0) clearBtn.style.display = 'inline-flex';\n        else clearBtn.style.display = 'none';\n    }\n\n    function formatDate(ts) {\n        const d = new Date(ts);\n        const today = new Date();\n        const isToday = d.toDateString() === today.toDateString();\n        const time = d.toLocaleTimeString('ru-RU', {hour: '2-digit', minute: '2-digit'});\n        if (isToday) return 'Сегодня, ' + time;\n        const yesterday = new Date(today);\n        yesterday.setDate(yesterday.getDate() - 1);\n        if (d.toDateString() === yesterday.toDateString()) return 'Вчера, ' + time;\n        return d.toLocaleDateString('ru-RU', {day: '2-digit', month: '2-digit', year: 'numeric'}) + ', ' + time;\n    }\n\n    function renderHistory() {\n        const arr = loadHistory();\n        const container = document.getElementById('historyContent');\n        updat");
